# generateStaticParams
Last updated October 1, 2026

The `generateStaticParams` function can be used in combination with [dynamic route segments](https://nextjs.org/docs/app/api-reference/file-conventions/dynamic-routes) to [**statically generate**](https://nextjs.org/docs/app/glossary#prerendering) routes at build time instead of on-demand at request time.

- You can use the [`dynamicParams`](https://nextjs.org/docs/app/api-reference/file-conventions/route-segment-config/dynamicParams) segment config option to control what happens when a dynamic segment is visited that was not generated with `generateStaticParams`.

## Single Dynamic Segment [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#single-dynamic-segment)
```
export function generateStaticParams() {
  return [{ id: '1' }, { id: '2' }, { id: '3' }]
}

// Three versions of this page will be statically generated
// using the `params` returned by `generateStaticParams`
// - /product/1
// - /product/2
// - /product/3
export default async function Page({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = await params
  // ...
}
```

## Multiple Dynamic Segments [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#multiple-dynamic-segments)
```
export function generateStaticParams() {
  return [\
    { category: 'a', product: '1' },\
    { category: 'b', product: '2' },\
    { category: 'c', product: '3' },\
  ]
}

// Three versions of this page will be statically generated
// using the `params` returned by `generateStaticParams`
// - /products/a/1
// - /products/b/2
// - /products/c/3
export default async function Page({
  params,
}: {
  params: Promise<{ category: string; product: string }>
}) {
  const { category, product } = await params
  // ...
}
```

## Catch-all Dynamic Segment [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#catch-all-dynamic-segment)
```
export function generateStaticParams() {
  return [{ slug: ['a', '1'] }, { slug: ['b', '2'] }, { slug: ['c', '3'] }]
}

// Three versions of this page will be statically generated
// using the `params` returned by `generateStaticParams`
// - /product/a/1
// - /product/b/2
// - /product/c/3
export default async function Page({
  params,
}: {
  params: Promise<{ slug: string[] }>
}) {
  const { slug } = await params
  // ...
}
```

## Examples [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#examples)
### Multiple Dynamic Segments in a Route [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#multiple-dynamic-segments-in-a-route)
#### Generate params from the bottom up [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#generate-params-from-the-bottom-up)
```
// Generate segments for both [category] and [product]
export async function generateStaticParams() {
  const products = await fetch('https://.../products').then((res) => res.json())

  return products.map((product) => ({
    category: product.category.slug,
    product: product.id,
  }))
}

export default function Page({
  params,
}: {
  params: Promise<{ category: string; product: string }>
}) {
  // ...
}
```

#### Generate params from the top down [Link to this section](https://nextjs.org/docs/app/api-reference/functions/generate-static-params#generate-params-from-the-top-down)
```
export async function generateStaticParams({
  params: { category },
}: {
  params: Awaited<LayoutProps<'/products/[category]'>['params']>
}) {
  const products = await fetch(
    `https://.../products?category=${category}`
  ).then((res) => res.json())

  return products.map((product) => ({
    product: product.id,
  }))
}
```
